head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > E > onsetdata]<br/>setJSON(), setXML() 메소드와 Submission 모듈로 Key 에 값(Value)이 설정되면 발생합니다.",
    "validation" : [
        "setJSON(), setXML() 메소드와 Submission 모듈로 Key 에 값(Value)이 설정되면 발생합니다.",
        "setArray() 메소드로 Key 에 값(Value) 설정 시 onsetdata 이벤트가 발생하지 않습니다.",
        "Key 가 바인드 되어 있는 컴포넌트에 값(Value)이 반영되기 전에 onsetdata 이벤트가 발생합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {      
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }  

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);  

    // target 생성
    $c.gcm.createBasicDataMap();

    // event 바인딩    
    target1.bind("onsetdata", function(info){
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onsetdata=====");
    });    

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');  
}   



scwin.btn_setJSON_onclick = function (e) {   
    target1.setJSON({key1:"key1_val1",key2:"key2_val2",key3:"key3_val3",key4:"key4_val4"});

    wf_body_bottom.getObj("scwin").setReturnValue("input1 value: " + input1.getValue());
};



scwin.btn_setXML_onclick = function (e) {   
    let xmlData = WebSquare.xml.parse('<map><key1>key1_val5</key1><key2>key2_val6</key2><key3>key3_val7</key3><key4>key4_val8</key4></map>');  
    target1.setXML(xmlData);

    wf_body_bottom.getObj("scwin").setReturnValue("input1 value: " + input1.getValue());
};



scwin.btn_setArray_onclick = function (e) {   
    target1.setArray(["key1_val9", "key2_val10", "key3_val11", "key4_val12"]);
};



scwin.btn_smReq_onclick = function (e) {
    $p.executeSubmission("sm_getData");
};
